package org.example.backend.controller;
import org.example.backend.entity.*;
import org.example.backend.service.*;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class ResourceEndpointBehaviorTest {
    final UsageRecordService usage=mock(UsageRecordService.class);
    final EnvironmentTemplateService templates=mock(EnvironmentTemplateService.class);
    final ConsumableService consumables=mock(ConsumableService.class);
    final RepairService repairs=mock(RepairService.class);
    final ModuleRecordService modules=mock(ModuleRecordService.class);
    final BusinessLoopService loop=mock(BusinessLoopService.class);
    MockMvc mvc;
    @BeforeEach void setup(){mvc=MockMvcBuilders.standaloneSetup(new UsageRecordController(usage),new EnvironmentTemplateController(templates),new ConsumableController(consumables),new RepairController(repairs),new SystemSettingsController(modules,loop)).build();}
    @Test void usageEndpointsMapStatusActionsAndBatchPayloadsToService() throws Exception{UsageRecordEntity record=new UsageRecordEntity();record.setId(7L);record.setResource("A101");when(usage.listUsageRecords()).thenReturn(List.of(record));when(usage.replaceUsageRecords(anyList())).thenAnswer(call->call.getArgument(0));when(usage.updateStatus(eq(7L),anyString())).thenAnswer(call->{UsageRecordEntity saved=new UsageRecordEntity();saved.setId(7L);saved.setStatus(call.getArgument(1));return saved;});mvc.perform(get("/usage-records")).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].resource").value("A101"));mvc.perform(put("/usage-records/batch").contentType(MediaType.APPLICATION_JSON).content("{\"resource\":\"usage-records\",\"records\":[{\"resource\":\"B202\"}]}" )).andExpect(jsonPath("$.data[0].resource").value("B202"));mvc.perform(put("/usage-records/batch").contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(jsonPath("$.data").isEmpty());for(String[] action:new String[][]{{"review","正常"},{"abnormal","异常"},{"archive","已归档"}})mvc.perform(post("/usage-records/7/"+action[0])).andExpect(jsonPath("$.data.status").value(action[1]));mvc.perform(post("/usage-records/reset")).andExpect(jsonPath("$.code").value(200));verify(usage).resetUsageRecords();}
    @Test void templateCrudAndTeacherOptionsPreserveResponseEnvelopes() throws Exception{EnvironmentTemplateEntity record=new EnvironmentTemplateEntity();record.setId(7L);record.setName("课程模板");when(templates.listTemplates()).thenReturn(List.of(record));when(templates.createTemplate(any())).thenAnswer(call->call.getArgument(0));when(templates.updateTemplate(eq(7L),any())).thenAnswer(call->call.getArgument(1));mvc.perform(get("/environment-templates")).andExpect(jsonPath("$.data[0].name").value("课程模板"));mvc.perform(post("/environment-templates").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"新模板\"}")).andExpect(jsonPath("$.data.name").value("新模板"));mvc.perform(put("/environment-templates/7").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"更新模板\"}")).andExpect(jsonPath("$.data.name").value("更新模板"));mvc.perform(delete("/environment-templates/7")).andExpect(jsonPath("$.code").value(200));verify(templates).deleteTemplate(7L);mvc.perform(put("/environment-templates/batch").contentType(MediaType.APPLICATION_JSON).content("{\"records\":[]}")).andExpect(jsonPath("$.code").value(200));verify(templates).replaceTemplates(List.of());mvc.perform(post("/environment-templates/reset")).andExpect(status().isOk());mvc.perform(get("/environment-templates/teachers")).andExpect(status().isOk());verify(templates).resetTemplates();verify(templates).listTeachers();}
    @Test void consumableMovementPathDoesNotCollideWithLoanResourceAndPassesNumericIdentity() throws Exception{ConsumableEntity record=new ConsumableEntity();record.setName("网线");when(consumables.listConsumables()).thenReturn(List.of(record));when(consumables.createConsumable(any())).thenAnswer(call->call.getArgument(0));when(consumables.updateConsumable(eq(7L),any())).thenAnswer(call->call.getArgument(1));ConsumableStockRecordEntity movement=new ConsumableStockRecordEntity();movement.setQuantity(2);when(consumables.recordConsumableMovement(eq(7L),any())).thenReturn(new ConsumableService.ConsumableMovementResult(record,movement,List.of(movement)));mvc.perform(get("/consumables")).andExpect(jsonPath("$.data[0].name").value("网线"));mvc.perform(post("/consumables/7/movement").contentType(MediaType.APPLICATION_JSON).content("{\"type\":\"out\",\"quantity\":2}")).andExpect(jsonPath("$.data.record.quantity").value(2));verify(consumables).recordConsumableMovement(eq(7L),argThat(item->item.getQuantity()==2));mvc.perform(get("/consumables/stock-records").param("consumableId","7")).andExpect(status().isOk());verify(consumables).listStockRecords(7L);mvc.perform(post("/consumables").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"电池\"}")).andExpect(jsonPath("$.data.name").value("电池"));mvc.perform(put("/consumables/7").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"电池二\"}")).andExpect(jsonPath("$.data.name").value("电池二"));mvc.perform(delete("/consumables/7")).andExpect(status().isOk());mvc.perform(put("/consumables/batch").contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isOk());mvc.perform(post("/consumables/reset")).andExpect(status().isOk());verify(consumables).deleteConsumable(7L);verify(consumables).replaceConsumables(List.of());verify(consumables).resetConsumables();}
    @Test void retiredRepairMutationsReturnGoneAndCannotInvokeOldWorkflow() throws Exception{mvc.perform(get("/repairs")).andExpect(status().isOk());mvc.perform(post("/repairs").contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isGone());mvc.perform(put("/repairs/7").contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isGone());mvc.perform(delete("/repairs/7")).andExpect(status().isGone());mvc.perform(put("/repairs/batch").contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isGone());for(String action:List.of("reset","7/assign","7/submit-acceptance","7/complete"))mvc.perform(post("/repairs/"+action)).andExpect(status().isGone());verify(repairs).listRepairs();verifyNoMoreInteractions(repairs);}
    @Test void systemSettingsDefaultsSaveAndResetKeepStableStorageIdentity() throws Exception{mvc.perform(get("/system-settings")).andExpect(jsonPath("$.data.basicConfig.dataRetention").value(180)).andExpect(jsonPath("$.data.loginPolicy.sessionTimeout").value(45));mvc.perform(put("/system-settings").contentType(MediaType.APPLICATION_JSON).content("{\"id\":\"untrusted\",\"basicConfig\":{\"platformName\":\"新平台\"}}" )).andExpect(jsonPath("$.data.id").value("system-settings"));verify(modules).replaceModuleRecords(eq("system-settings"),argThat(records->records.size()==1&&records.get(0).get("id").equals("system-settings")));when(modules.listModuleRecords("system-settings")).thenReturn(List.of(Map.of("id","system-settings","custom",true)));mvc.perform(get("/system-settings")).andExpect(jsonPath("$.data.custom").value(true));mvc.perform(post("/system-settings/reset")).andExpect(jsonPath("$.data.aiSettings.timeout").value(30));verify(loop).recordEvent(eq("system-settings"),eq("reset"),anyString(),anyString(),eq(Map.of("sectionCount",3)));}
}
